mapper.select:
SELECT /*selectMasterMpRqItemReqStndList*/ ROWNUM AS NO , Y.BUYER , Y.RAV_NO , Y.RAV_SEQ , Y.STATUS , Y.RFQ_USER_ID , Y.RFQ_USER_NAME , Y.BUYER_ITEM_NO , Y.ITEM_STATUS , Y.DESCRIPTION , Y.SPECIFICATION , Y.UNIT_MEASURE , Y.MAKER_NAME , Y.BUYER_REMARK , Y.KEP_RAV_SEQ , Y.KEP_BUYER_ITEM_NO , Y.KEP_ITEM_STATUS , Y.KEP_DESCRIPTION , Y.KEP_SPECIFICATION , Y.KEP_UNIT_MEASURE , Y.KEP_MAKER_NAME , Y.KEP_KEP_REMARK , Y.KEP_MAKER_CODE , Y.ORIGIN_CODE , Y.ORIGIN_NAME , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.IMAGE_KEY , DECODE(Y.BUYER_REMARK,'',0,1) AS KEP_KEP_REMARK_IMG , DECODE(Y.IMAGE_KEY,'',2,3) AS IMAGE_KEY_IMG FROM( SELECT ROWNUM NUM , X.BUYER , X.RAV_NO , X.RAV_SEQ , X.STATUS , X.RFQ_USER_ID , X.RFQ_USER_NAME , X.BUYER_ITEM_NO , X.ITEM_STATUS , X.DESCRIPTION , X.SPECIFICATION , X.UNIT_MEASURE , X.MAKER_NAME , X.BUYER_REMARK , X.KEP_RAV_SEQ , X.KEP_BUYER_ITEM_NO , X.KEP_ITEM_STATUS , X.KEP_DESCRIPTION , X.KEP_SPECIFICATION , X.KEP_MAKER_NAME , X.KEP_MAKER_CODE , X.KEP_UNIT_MEASURE , X.KEP_KEP_REMARK , X.ORIGIN_CODE , X.ORIGIN_NAME , X.CONTRACT_NO , X.CONTRACT_SEQ , X.IMAGE_KEY FROM( SELECT A.BUYER , A.RAV_NO , A.RAV_SEQ , A.STATUS , A.RFQ_USER_ID , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.RFQ_USER_ID) AS RFQ_USER_NAME , A.BUYER_ITEM_NO , A.ITEM_STATUS , A.DESCRIPTION , A.SPECIFICATION , A.UNIT_MEASURE , A.MAKER_NAME , A.BUYER_REMARK , NVL(B.RAV_SEQ, A.RAV_SEQ) AS KEP_RAV_SEQ , NVL(B.BUYER_ITEM_NO, A.BUYER_ITEM_NO) AS KEP_BUYER_ITEM_NO , NVL(B.ITEM_STATUS, A.ITEM_STATUS) AS KEP_ITEM_STATUS , NVL(B.DESCRIPTION, A.DESCRIPTION) AS KEP_DESCRIPTION , NVL(B.SPECIFICATION, A.SPECIFICATION) AS KEP_SPECIFICATION , NVL(B.MAKER_NAME, A.MAKER_NAME) AS KEP_MAKER_NAME , NVL(B.MAKER_CODE, '') AS KEP_MAKER_CODE , NVL(B.UNIT_MEASURE, A.UNIT_MEASURE) AS KEP_UNIT_MEASURE , NVL(B.ORIGIN_CODE, '') AS ORIGIN_CODE , NVL(B.ORIGIN_NAME, '') AS ORIGIN_NAME , NVL(B.CONTRACT_NO, '') AS CONTRACT_NO , NVL(B.CONTRACT_SEQ, '') AS CONTRACT_SEQ , B.KEP_REMARK AS KEP_KEP_REMARK , A.IMAGE_KEY FROM TBL_RFQ_ATTRI_VERIFY A, TBL_RFQ_ATTRI_VERIFY B WHERE 1=1
AND A.BUYER = #{st_buyer_code}
AND A.BUYER = B.BUYER(+) AND A.REQ_DATE BETWEEN #{st_req_from_date} AND #{st_req_to_date}
AND A.RAV_NO LIKE #{st_ser_rav_no}||'%'
AND A.RFQ_USER_ID = #{st_btoa_user_id}
AND A.DESCRIPTION LIKE '%'||#{st_se_description}||'%'
AND A.RAV_NO = B.RAV_NO(+) AND A.RAV_SEQ = 1 AND B.RAV_SEQ(+) = 2 AND A.STATUS = 'C' ORDER BY A.RAV_NO )X ) Y


        SELECT COUNT(*) AS CNT	 /*mailMasterMpRqItemReqStndCnt*/		  		
			  FROM MAILSEND			  		
			 WHERE MAILFORM_ID ='RFQ_VERIFY_FB_MB'	
			  AND KEY1 = #{BUYER}	  		
			  AND KEY2 = #{RAV_NO}			
			  AND KEY3 = #{RAV_SEQ}

SELECT /*selectMasterMpRqItemReqStndList*/ ROWNUM AS NO , Y.BUYER , Y.RAV_NO , Y.RAV_SEQ , Y.STATUS , Y.RFQ_USER_ID , Y.RFQ_USER_NAME , Y.BUYER_ITEM_NO , Y.ITEM_STATUS , Y.DESCRIPTION , Y.SPECIFICATION , Y.UNIT_MEASURE , Y.MAKER_NAME , Y.BUYER_REMARK , Y.KEP_RAV_SEQ , Y.KEP_BUYER_ITEM_NO , Y.KEP_ITEM_STATUS , Y.KEP_DESCRIPTION , Y.KEP_SPECIFICATION , Y.KEP_UNIT_MEASURE , Y.KEP_MAKER_NAME , Y.KEP_KEP_REMARK , Y.KEP_MAKER_CODE , Y.ORIGIN_CODE , Y.ORIGIN_NAME , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.IMAGE_KEY , DECODE(Y.BUYER_REMARK,'',0,1) AS KEP_KEP_REMARK_IMG , DECODE(Y.IMAGE_KEY,'',2,3) AS IMAGE_KEY_IMG FROM( SELECT ROWNUM NUM , X.BUYER , X.RAV_NO , X.RAV_SEQ , X.STATUS , X.RFQ_USER_ID , X.RFQ_USER_NAME , X.BUYER_ITEM_NO , X.ITEM_STATUS , X.DESCRIPTION , X.SPECIFICATION , X.UNIT_MEASURE , X.MAKER_NAME , X.BUYER_REMARK , X.KEP_RAV_SEQ , X.KEP_BUYER_ITEM_NO , X.KEP_ITEM_STATUS , X.KEP_DESCRIPTION , X.KEP_SPECIFICATION , X.KEP_MAKER_NAME , X.KEP_MAKER_CODE , X.KEP_UNIT_MEASURE , X.KEP_KEP_REMARK , X.ORIGIN_CODE , X.ORIGIN_NAME , X.CONTRACT_NO , X.CONTRACT_SEQ , X.IMAGE_KEY FROM( SELECT A.BUYER , A.RAV_NO , A.RAV_SEQ , A.STATUS , A.RFQ_USER_ID , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.RFQ_USER_ID) AS RFQ_USER_NAME , A.BUYER_ITEM_NO , A.ITEM_STATUS , A.DESCRIPTION , A.SPECIFICATION , A.UNIT_MEASURE , A.MAKER_NAME , A.BUYER_REMARK , NVL(B.RAV_SEQ, A.RAV_SEQ) AS KEP_RAV_SEQ , NVL(B.BUYER_ITEM_NO, A.BUYER_ITEM_NO) AS KEP_BUYER_ITEM_NO , NVL(B.ITEM_STATUS, A.ITEM_STATUS) AS KEP_ITEM_STATUS , NVL(B.DESCRIPTION, A.DESCRIPTION) AS KEP_DESCRIPTION , NVL(B.SPECIFICATION, A.SPECIFICATION) AS KEP_SPECIFICATION , NVL(B.MAKER_NAME, A.MAKER_NAME) AS KEP_MAKER_NAME , NVL(B.MAKER_CODE, '') AS KEP_MAKER_CODE , NVL(B.UNIT_MEASURE, A.UNIT_MEASURE) AS KEP_UNIT_MEASURE , NVL(B.ORIGIN_CODE, '') AS ORIGIN_CODE , NVL(B.ORIGIN_NAME, '') AS ORIGIN_NAME , NVL(B.CONTRACT_NO, '') AS CONTRACT_NO , NVL(B.CONTRACT_SEQ, '') AS CONTRACT_SEQ , B.KEP_REMARK AS KEP_KEP_REMARK , A.IMAGE_KEY FROM TBL_RFQ_ATTRI_BOARD A, TBL_RFQ_ATTRI_BOARD B WHERE 1=1
AND A.BUYER = #{st_buyer_code}
AND A.BUYER = B.BUYER(+) AND A.REQ_DATE BETWEEN #{st_req_from_date} AND #{st_req_to_date}
AND A.RAV_NO LIKE #{st_ser_rav_no}||'%'
AND A.RFQ_USER_ID = #{st_btoa_user_id}
AND A.DESCRIPTION LIKE '%'||#{st_se_description}||'%'
AND A.RAV_NO = B.RAV_NO(+) AND A.RAV_SEQ = 1 AND B.RAV_SEQ(+) = 2 AND A.STATUS = 'C' ORDER BY A.RAV_NO )X ) Y
